"""Tests for Overconfidence Identifier in Conclusive Language — auto-generated by SUSHILOOP."""
import sys
from pathlib import Path
sys.path.insert(0, str(Path(__file__).parent.parent / 'skills'))
from overconfidence_identifier_in_conclusive_language import overconfidence_identifier_in_conclusive_language

EDGE_INPUTS = ["", "   ", "a", "hello", "no punct here", None, "12345", "\n\n"]

def test_returns_dict_on_all_edges():
    for inp in EDGE_INPUTS:
        out = overconfidence_identifier_in_conclusive_language(inp)
        assert isinstance(out, dict), f"non-dict on {inp!r}"
        assert "blocked" in out and "confidence" in out, f"missing keys on {inp!r}"

def test_confidence_in_range():
    for inp in EDGE_INPUTS:
        c = overconfidence_identifier_in_conclusive_language(inp).get("confidence")
        assert isinstance(c, (int, float)) and 0.0 <= c <= 1.0
